/**
 * Text measurement behind one interface (`TextMeasurer`), so layout never calls browser APIs.
 *
 * `createFontSetMeasurer` is the deterministic implementation: it reads the pinned font files (sha256-verified) and
 * gives byte-identical results in Node (compile service, tests, QC) and in the browser bundle (Spark preview, frame
 * service). A browser-side measurer (canvas/DOM) may implement the same interface for parity checks in the Chromium
 * frame service (P06-45); layouts are always computed once and stored in the IR, so preview and final render the same
 * line breaks and sizes regardless of which host renders them.
 */
import { MotionError } from '../errors'
import { canonicalJson } from '../ir/canonical'
import { parseFont, type ParsedFont } from './font'
import { otLanguage, primaryOtScript } from './segment'
import { sha256Hex } from './sha256'

export type FontStyle = 'normal' | 'italic'

export interface FontRequest {
  family: string
  weight: number
  style?: FontStyle
}

export interface FontFaceDescriptor {
  family: string
  weight: number
  style: FontStyle
  /** sha256 of the font file bytes (catalogue pin). */
  sha256: string
}

export interface PinnedFontFace extends FontFaceDescriptor {
  bytes: Uint8Array
}

export interface LineMetrics {
  ascent: number
  descent: number
  line_gap: number
}

export interface TextMeasurer {
  /** Identity of the pinned font set; layouts record it and renderers must pin the same set. */
  readonly font_set_hash: string
  hasFace(font: FontRequest): boolean
  /** Face line metrics in px at `sizePx`. */
  lineMetrics(font: FontRequest, sizePx: number): LineMetrics
  /**
   * Advances in px of consecutive grapheme clusters shaped as one run: kerning between neighbouring clusters is
   * applied, so `sum(advances)` is the run width and the prefix sums are the cluster x positions.
   */
  advances(clusters: readonly string[], font: FontRequest, sizePx: number, lang: string): number[]
  /** Code points of `cluster` the face has no glyph for (F45: zero `.notdef`). */
  missingGlyphs(cluster: string, font: FontRequest): number[]
}

const SHA256 = /^[0-9a-f]{64}$/

const faceKey = (font: { family: string; weight: number; style?: FontStyle }): string => `${font.family}\u0000${font.weight}\u0000${font.style ?? 'normal'}`

/** sha256 over the canonical, order-independent list of face descriptors (family, weight, style, file sha256). */
export function fontSetHash(faces: readonly FontFaceDescriptor[]): string {
  const sorted = faces
    .map((face) => ({ family: face.family, weight: face.weight, style: face.style, sha256: face.sha256 }))
    .sort((a, b) => (faceKey(a) < faceKey(b) ? -1 : faceKey(a) > faceKey(b) ? 1 : 0))
  return sha256Hex(canonicalJson({ font_set: sorted }))
}

const IGNORABLE = /\p{Default_Ignorable_Code_Point}/u
const MARK = /\p{M}/u
const SPACING_MARK = /\p{Mc}/u

export function createFontSetMeasurer(faces: readonly PinnedFontFace[]): TextMeasurer {
  if (faces.length === 0) throw new MotionError('font_refused', 'a font set needs at least one face')
  const parsed = new Map<string, ParsedFont>()
  for (const face of faces) {
    if (!SHA256.test(face.sha256)) throw new MotionError('font_refused', `${face.family} ${face.weight}: sha256 pin must be 64 lowercase hex`)
    const actual = sha256Hex(face.bytes)
    if (actual !== face.sha256) {
      throw new MotionError('font_refused', `${face.family} ${face.weight}: file sha256 ${actual} does not match the pinned ${face.sha256}`, [
        { code: 'font_pin_mismatch', path: `/fonts/${face.family}`, message: 'font bytes differ from the catalogue pin' },
      ])
    }
    const key = faceKey(face)
    if (parsed.has(key)) throw new MotionError('font_refused', `duplicate face ${face.family} ${face.weight} ${face.style}`)
    parsed.set(key, parseFont(face.bytes))
  }
  const hash = fontSetHash(faces)

  const faceOf = (font: FontRequest): ParsedFont => {
    const face = parsed.get(faceKey(font))
    if (!face) {
      throw new MotionError('font_refused', `font set ${hash.slice(0, 12)} has no face ${font.family} ${font.weight} ${font.style ?? 'normal'}`, [
        { code: 'font_missing', path: '/font', message: `${font.family} ${font.weight} is not in the pinned font set (no synthesis, no fallback)` },
      ])
    }
    return face
  }

  return {
    font_set_hash: hash,
    hasFace: (font) => parsed.has(faceKey(font)),
    lineMetrics(font, sizePx) {
      const face = faceOf(font)
      const scale = sizePx / face.units_per_em
      return { ascent: face.ascender * scale, descent: -face.descender * scale, line_gap: face.line_gap * scale }
    },
    advances(clusters, font, sizePx, lang) {
      const face = faceOf(font)
      const script = primaryOtScript(clusters.join(''))
      const language = otLanguage(lang)
      const scale = sizePx / face.units_per_em
      const units: number[] = []
      let previousBase = -1
      clusters.forEach((cluster, index) => {
        let advance = 0
        let firstBase = -1
        let lastBase = -1
        for (const char of cluster) {
          if (IGNORABLE.test(char) || char === '\n') continue
          const glyph = face.localize(face.glyph(char.codePointAt(0) as number), script, language)
          // Combining marks are zero-advance (HarfBuzz zero-width marks); spacing marks keep their advance.
          const isMark = MARK.test(char) && !SPACING_MARK.test(char)
          if (!isMark) {
            advance += face.advance(glyph)
            if (firstBase < 0) firstBase = glyph
            lastBase = glyph
          }
        }
        if (previousBase >= 0 && firstBase >= 0) {
          const pair = face.kerning(previousBase, firstBase, script, language)
          units[index - 1] = (units[index - 1] as number) + pair.first
          advance += pair.second
        }
        units.push(advance)
        if (lastBase >= 0) previousBase = lastBase
      })
      return units.map((value) => value * scale)
    },
    missingGlyphs(cluster, font) {
      const face = faceOf(font)
      const missing: number[] = []
      for (const char of cluster) {
        if (IGNORABLE.test(char) || char === '\n') continue
        const codepoint = char.codePointAt(0) as number
        if (face.glyph(codepoint) === 0) missing.push(codepoint)
      }
      return missing
    },
  }
}
